$u=(int)($_SESSION['id_usuario']??0);$e=(int)($_SESSION['id_empresa']??0);exigir_permiso_accion($pdo,$u,$e,'oracle_pagos');$empresa=(string)($_SESSION['empresa_nombre']??'Empresa activa');if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$anio=(int)date('Y');$mes=(int)date('n');
