.oic-card{background:#fff;border:1px solid #d9e2ec;border-radius:12px;color:#172b3a}.oic-kpi{background:#f7f9fc;border:1px solid #dce5ef;border-radius:10px;padding:12px}.oic-kpi b{font-size:1.15rem}.oic-table{font-size:.83rem}.oic-table td,.oic-table th{vertical-align:middle}.oic-pill{font-size:.72rem}.oic-exp-detail{background:#fbfcfe}.oic-tabs .nav-link{color:#3a5068}.oic-tabs .nav-link.active{font-weight:700;color:#0d6efd}.oic-scroll{max-height:560px;overflow:auto;border:1px solid #e7edf3;border-radius:8px}.oic-scroll table{margin-bottom:0}.oic-scroll thead th{position:sticky;top:0;z-index:5;background:#eaf2f8;box-shadow:0 1px 0 #cfd8e3}.oic-exp-list{max-height:590px;overflow:auto;padding-right:2px}.oic-exp-item{border:1px solid #dbe4ec;border-radius:10px;margin-bottom:8px;background:#fff;overflow:hidden}.oic-exp-head{width:100%;border:0;background:#f8fafc;padding:10px 12px;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:12px}.oic-exp-head:hover{background:#eef5fb}.oic-exp-left{display:flex;align-items:center;gap:8px;min-width:0}.oic-exp-ref{font-weight:700}.oic-exp-arrow{transition:transform .18s ease}.oic-exp-head[aria-expanded="true"] .oic-exp-arrow{transform:rotate(90deg)}.oic-exp-totals{white-space:nowrap;font-size:.85rem}.oic-exp-body{border-top:1px solid #e5ebf0}.oic-exp-body .oic-scroll{max-height:320px;border:0;border-radius:0}
